    public static void initConfig(FMLPreInitializationEvent e) {
        File directory = e.getModConfigurationDirectory();
        CommonProxy.config = new Configuration(new File(directory.getPath(), "subspaceparasite/SPParasites.cfg"));
        SPConfig.readConfig();
    }

    public static boolean readConfig() {
        Configuration cfg = CommonProxy.config;
        try {
            cfg.load();
            SPConfig.initGeneralConfig(cfg);
            SPConfig.initPropertiesConfig(cfg);
            SPConfig.initPropertiesConfigSim(cfg);
            SPConfig.initPropertiesConfigMar(cfg);
            SPConfig.initPropertiesConfigFeral(cfg);
            SPConfig.initPropertiesConfigHi(cfg);
            SPConfig.initPropertiesConfigPri(cfg);
            SPConfig.initPropertiesConfigAda(cfg);
            SPConfig.initPropertiesConfigPure(cfg);
            SPConfig.initPropertiesConfigPreeminent(cfg);
            SPConfig.initPropertiesConfigDer(cfg);
            SPConfig.initPropertiesConfigAnc(cfg);
            SPConfig.initPropertiesConfigNex(cfg);
            SPConfig.initPropertiesConfigDet(cfg);
            SPConfig.initgearConfig(cfg);
            boolean bl = true;
            return bl;
        }
        catch (Exception e) {
            SPMain.logger.log(Level.ERROR, "Problem loading configuration file", (Throwable)e);
        }
        finally {
            if (cfg.hasChanged()) {
                cfg.save();
            }
        }
        return false;
    }

